public class ExchangeRateClient {

    public class ExchangeRateException extends Exception {}

    private static final String ENDPOINT_BASE = 'callout:FB_Exchange_Rates/v1/latest';
    private static final Integer HTTP_OK = 200;
    private static final Integer HTTP_SERVICE_UNAVAILABLE = 503;
    private static final String CODE_PATTERN = '[A-Z]{3}';

    public class RatesResponse {
        public Map<String, Decimal> rates;
    }

    public static Map<String, Decimal> getRates(String baseCurrency, Set<String> quoteCurrencies) {
        String base = normaliseCode(baseCurrency);

        if (quoteCurrencies == null || quoteCurrencies.isEmpty()) {
            throw new ExchangeRateException('At least one quote currency code is required');
        }

        Set<String> quotes = new Set<String>();
        for (String quote : quoteCurrencies) {
            quotes.add(normaliseCode(quote));
        }

        List<String> sortedQuotes = new List<String>(quotes);
        sortedQuotes.sort();

        String symbols = '';
        for (Integer i = 0; i < sortedQuotes.size(); i++) {
            if (i > 0) {
                symbols += ',';
            }
            symbols += sortedQuotes[i];
        }

        HttpRequest req = new HttpRequest();
        req.setEndpoint(ENDPOINT_BASE + '?base=' + base + '&symbols=' + symbols);
        req.setMethod('GET');
        req.setHeader('Accept', 'application/json');

        Http http = new Http();
        HttpResponse res = http.send(req);

        // Retry exactly once on 503 with an identical request.
        if (res.getStatusCode() == HTTP_SERVICE_UNAVAILABLE) {
            res = http.send(req);
        }

        if (res.getStatusCode() != HTTP_OK) {
            throw new ExchangeRateException(
                'Exchange rate request failed with HTTP status ' + res.getStatusCode()
            );
        }

        String body = res.getBody();
        if (String.isBlank(body)) {
            throw new ExchangeRateException('Exchange rate response body is empty');
        }

        RatesResponse parsed;
        try {
            parsed = (RatesResponse) JSON.deserialize(body, RatesResponse.class);
        } catch (Exception e) {
            throw new ExchangeRateException('Exchange rate response body could not be parsed');
        }

        if (parsed == null || parsed.rates == null) {
            throw new ExchangeRateException('Exchange rate response contains no rates');
        }

        Map<String, Decimal> result = new Map<String, Decimal>();
        for (String quote : quotes) {
            Decimal rate = parsed.rates.get(quote);
            if (rate == null) {
                throw new ExchangeRateException('Exchange rate response has no rate for ' + quote);
            }
            result.put(quote, rate);
        }

        return result;
    }

    private static String normaliseCode(String code) {
        if (code == null) {
            throw new ExchangeRateException('Currency code must not be null');
        }

        String normalised = code.trim().toUpperCase();
        // Pattern.matches requires the whole input to match the regex.
        if (!Pattern.matches(CODE_PATTERN, normalised)) {
            throw new ExchangeRateException('Currency code must be exactly three letters A-Z');
        }

        return normalised;
    }
}
```

The compile error came from `String.matches(...)`, which does not exist in Apex. The validation now uses `Pattern.matches('[A-Z]{3}', normalised)`, which requires the entire trimmed, upper-cased code to match. The rest of the class is unchanged apart from the parse block, which now catches `Exception` so that any deserialisation failure is reported as an `ExchangeRateException`.

