@IsTest
private class OpportunityCleanupServiceTest {

    private static final Date CUTOFF = Date.newInstance(2024, 6, 1);
    private static final String ORIGINAL_DESCRIPTION = 'Original description';

    private static fflib_ApexMocks mocks;
    private static fflib_ISObjectUnitOfWork uowMock;
    private static IOpportunitiesSelector selectorMock;

    // ---------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------

    private static Opportunity buildOpp(String stageName, Date closeDate) {
        return new Opportunity(
            Id = fflib_IDGenerator.generate(Opportunity.SObjectType),
            Name = 'Test Opportunity',
            StageName = stageName,
            CloseDate = closeDate,
            Description = ORIGINAL_DESCRIPTION
        );
    }

    private static Set<Id> idsOf(List<Opportunity> opps) {
        Set<Id> ids = new Set<Id>();
        for (Opportunity opp : opps) {
            ids.add(opp.Id);
        }
        return ids;
    }

    // The same Set instance must be passed to the stub and to closeStale so the
    // ApexMocks argument matching is guaranteed to succeed.
    private static void wire(Set<Id> ids, List<Opportunity> opps) {
        mocks = new fflib_ApexMocks();
        uowMock = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);
        selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);

        mocks.startStubbing();
        mocks.when(selectorMock.selectById(ids)).thenReturn(opps);
        mocks.stopStubbing();

        Application.UnitOfWork.setMock(uowMock);
        Application.Selector.setMock(selectorMock);
    }

    private static void verifyRegistered(Opportunity opp) {
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 1)).registerDirty(opp);
    }

    private static void verifyNotRegistered(Opportunity opp) {
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, 0)).registerDirty(opp);
    }

    private static void verifyCommitCount(Integer times) {
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, times)).commitWork();
    }

    private static void assertClosed(Opportunity opp) {
        System.assertEquals('Closed Lost', opp.StageName, 'Stale opportunity should be Closed Lost');
        System.assertEquals(
            OpportunityCleanupService.LOST_REASON,
            opp.Description,
            'Stale opportunity should carry the lost reason'
        );
    }

    private static void assertUntouched(Opportunity opp, String expectedStage) {
        System.assertEquals(expectedStage, opp.StageName, 'Non-stale opportunity stage must not change');
        System.assertEquals(
            ORIGINAL_DESCRIPTION,
            opp.Description,
            'Non-stale opportunity description must not change'
        );
    }

    // ---------------------------------------------------------------------
    // Tests
    // ---------------------------------------------------------------------

    @IsTest
    static void closesOnlyStaleOpportunitiesAndReturnsCount() {
        Opportunity staleA = buildOpp('Prospecting', Date.newInstance(2024, 1, 15));
        Opportunity staleB = buildOpp('Negotiation/Review', Date.newInstance(2024, 5, 31));
        Opportunity onCutoff = buildOpp('Prospecting', CUTOFF);
        Opportunity future = buildOpp('Prospecting', Date.newInstance(2024, 7, 1));
        Opportunity wonPast = buildOpp('Closed Won', Date.newInstance(2024, 1, 1));
        Opportunity lostPast = buildOpp('Closed Lost', Date.newInstance(2024, 1, 1));
        Opportunity noCloseDate = buildOpp('Prospecting', null);

        List<Opportunity> opps = new List<Opportunity>{
            staleA, staleB, onCutoff, future, wonPast, lostPast, noCloseDate
        };
        Set<Id> ids = idsOf(opps);
        wire(ids, opps);

        Integer closed = OpportunityCleanupService.closeStale(ids, CUTOFF);

        System.assertEquals(2, closed, 'Only the two stale opportunities should be closed');

        // Stale opportunities are closed and registered exactly once each.
        assertClosed(staleA);
        assertClosed(staleB);
        verifyRegistered(staleA);
        verifyRegistered(staleB);

        // Everything else is left alone and never registered.
        assertUntouched(onCutoff, 'Prospecting');
        assertUntouched(future, 'Prospecting');
        assertUntouched(wonPast, 'Closed Won');
        assertUntouched(lostPast, 'Closed Lost');
        assertUntouched(noCloseDate, 'Prospecting');
        verifyNotRegistered(onCutoff);
        verifyNotRegistered(future);
        verifyNotRegistered(wonPast);
        verifyNotRegistered(lostPast);
        verifyNotRegistered(noCloseDate);

        verifyCommitCount(1);
    }

