```apex
public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    private static final String CREDIT_REVIEW_FIELD_SET = 'Credit_Review';

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    public List<Schema.SObjectField> getSObjectFieldList() {
        return new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };
    }

    /**
     * Accounts by Id, with base fields plus every field currently on the
     * Credit_Review field set. Runs in user mode so object, field and sharing
     * access of the running user is enforced by the platform.
     */
    public List<Account> selectById(Set<Id> accountIds) {
        String soql = 'SELECT ' + String.join(getAccountFieldNames(), ', ') +
            ' FROM Account WHERE Id IN :accountIds WITH USER_MODE';
        return (List<Account>) Database.query(soql);
    }

    /**
     * Accounts by Id with their Contacts child records in the same query.
     * Contact fields come from ContactsSelector. Runs in user mode.
     */
    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        String soql = 'SELECT ' + String.join(getAccountFieldNames(), ', ') +
            ', (SELECT ' + String.join(getContactFieldNames(), ', ') + ' FROM Contacts)' +
            ' FROM Account WHERE Id IN :accountIds WITH USER_MODE';
        return (List<Account>) Database.query(soql);
    }

    /**
     * Base Account fields plus the current members of the Credit_Review field set,
     * de-duplicated (case-insensitive). Read at runtime so admin changes to the
     * field set need no code change.
     */
    private List<String> getAccountFieldNames() {
        List<String> names = new List<String>();
        Set<String> seen = new Set<String>();

        for (Schema.SObjectField field : getSObjectFieldList()) {
            addFieldName(names, seen, field.getDescribe().getName());
        }

        Schema.FieldSet creditReview = Schema.SObjectType.Account.fieldSets.getMap().get(CREDIT_REVIEW_FIELD_SET);
        if (creditReview != null) {
            for (Schema.FieldSetMember member : creditReview.getFields()) {
                addFieldName(names, seen, member.getFieldPath());
            }
        }
        return names;
    }

    /**
     * Contact fields as defined by ContactsSelector, used for the child subquery.
     */
    private List<String> getContactFieldNames() {
        List<String> names = new List<String>();
        Set<String> seen = new Set<String>();
        for (Schema.SObjectField field : new ContactsSelector().getSObjectFieldList()) {
            addFieldName(names, seen, field.getDescribe().getName());
        }
        return names;
    }

    private static void addFieldName(List<String> names, Set<String> seen, String fieldName) {
        if (String.isNotBlank(fieldName) && seen.add(fieldName.toLowerCase())) {
            names.add(fieldName);
        }
    }
}
