public with sharing class DealEventPublisher {

    /**
     * Publishes one Deal_Stage_Change__e platform event per Opportunity.
     *
     * All events are published with a single EventBus.publish(List) call. A publish
     * call counts against the 150-per-transaction limit, so a loop of one call per
     * opportunity would exceed that limit for a full 200-record trigger batch.
     *
     * The returned list is in the same order as the input: index i of the result
     * corresponds to opportunities[i].
     *
     * @param opportunities  Opportunities to publish stage changes for. May be null or empty.
     * @return               One Database.SaveResult per input opportunity, in input order.
     *                       An empty list is returned when there is nothing to publish.
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        List<Database.SaveResult> results = new List<Database.SaveResult>();
        if (opportunities == null || opportunities.isEmpty()) {
            return results;
        }

        List<Deal_Stage_Change__e> events = new List<Deal_Stage_Change__e>();
        for (Opportunity opp : opportunities) {
            events.add(buildEvent(opp));
        }

        // Single publish call for the whole batch. Results are returned in input order.
        List<Database.SaveResult> publishResults = EventBus.publish(events);
        if (publishResults != null) {
            results.addAll(publishResults);
        }
        return results;
    }

    /**
     * Builds the platform event payload for one opportunity.
     * String.valueOf(Id) returns the 18-character form, even if the Id was
     * originally supplied as 15 characters.
     */
    private static Deal_Stage_Change__e buildEvent(Opportunity opp) {
        Deal_Stage_Change__e evt = new Deal_Stage_Change__e();
        if (opp == null) {
            return evt;
        }
        evt.Opportunity_Id__c = (opp.Id == null) ? null : String.valueOf(opp.Id);
        evt.Stage__c = opp.StageName;
        evt.Amount__c = opp.Amount;
        return evt;
    }
}
