} from 'lightning/messageService';
import ACCOUNT_SELECTED_CHANNEL from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    recordId = null;
    subscription = null;

    @wire(MessageContext)
    messageContext;

    connectedCallback() {
        this.subscribeToMessageChannel();
    }

    disconnectedCallback() {
        this.unsubscribeFromMessageChannel();
    }

    get hasRecord() {
        return !!this.recordId;
    }

    subscribeToMessageChannel() {
        // Never hold more than one subscription.
        if (this.subscription) {
            return;
        }
        this.subscription = subscribe(
            this.messageContext,
            ACCOUNT_SELECTED_CHANNEL,
            (message) => this.handleMessage(message),
            { scope: APPLICATION_SCOPE }
        );
    }

    unsubscribeFromMessageChannel() {
        if (this.subscription) {
            unsubscribe(this.subscription);
            this.subscription = null;
        }
    }

    handleMessage(message) {
        this.recordId = message && message.recordId ? message.recordId : null;
    }

    handleClear() {
        // This component is subscribed too, so it clears its own view via handleMessage.
        publish(this.messageContext, ACCOUNT_SELECTED_CHANNEL, { recordId: null });
    }
