/**
 * Adds NPSP partial soft credits for fundraisers on opportunities.
 *
 * For each request the contact ends up with exactly one OpportunityContactRole on the
 * opportunity (Role = request role) and exactly one npsp__Partial_Soft_Credit__c
 * (amount and role from the request) linked to that contact role.
 *
 * Bulk budget: 3 SOQL queries and at most 4 DML statements per call, independent of
 * the number of requests.
 *
 * All validation runs before the first DML statement, so a rejected call changes nothing.
 * DML is all-or-nothing: any failure rolls back the whole transaction.
 *
 * DML is performed only on minimal records (Id plus the fields this service intends to
 * change) so that no read-only or non-updateable field loaded by the queries is sent back
 * to the database.
 */
public with sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // ---------------------------------------------------------------
        // Pass 1: structural validation and key collection (no SOQL/DML)
        // ---------------------------------------------------------------
        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        Set<String> seenPairs = new Set<String>();

        for (SoftCreditRequest req : requests) {
            if (req == null) {
                throw new SoftCreditException('Soft credit request cannot be null.');
            }
            if (req.opportunityId == null || req.contactId == null) {
                throw new SoftCreditException('Every soft credit request needs an opportunityId and a contactId.');
            }
            if (String.isBlank(req.role)) {
                throw new SoftCreditException('Every soft credit request needs a role (contact ' + req.contactId + ').');
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Soft credit amount must be a positive value (contact ' + req.contactId + ').');
            }
            if (!seenPairs.add(pairKey(req.opportunityId, req.contactId))) {
                throw new SoftCreditException(
                    'Duplicate opportunity/contact pair in one call (contact ' + req.contactId +
                    ', opportunity ' + req.opportunityId + ').'
                );
            }
            oppIds.add(req.opportunityId);
            contactIds.add(req.contactId);
        }

        // ---------------------------------------------------------------
        // Pass 2: bulk reads (3 SOQL queries in total)
        // ---------------------------------------------------------------
        Map<Id, Opportunity> oppsById = new Map<Id, Opportunity>(
            [SELECT Id, Amount, npsp__Primary_Contact__c
               FROM Opportunity
              WHERE Id IN :oppIds
             WITH USER_MODE]
        );

        Map<String, List<OpportunityContactRole>> ocrsByPair = new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
                SELECT Id, OpportunityId, ContactId, Role, IsPrimary
                  FROM OpportunityContactRole
                 WHERE OpportunityId IN :oppIds
                   AND ContactId IN :contactIds
                 WITH USER_MODE
        ]) {
            String key = pairKey(ocr.OpportunityId, ocr.ContactId);
            if (!ocrsByPair.containsKey(key)) {
                ocrsByPair.put(key, new List<OpportunityContactRole>());
            }
            ocrsByPair.get(key).add(ocr);
        }

        Map<String, List<npsp__Partial_Soft_Credit__c>> pscsByPair = new Map<String, List<npsp__Partial_Soft_Credit__c>>();
        for (npsp__Partial_Soft_Credit__c psc : [
                SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c,
                       npsp__Role_Name__c, npsp__Contact_Role_ID__c
                  FROM npsp__Partial_Soft_Credit__c
                 WHERE npsp__Opportunity__c IN :oppIds
                   AND npsp__Contact__c IN :contactIds
                 WITH USER_MODE
        ]) {
            String key = pairKey(psc.npsp__Opportunity__c, psc.npsp__Contact__c);
            if (!pscsByPair.containsKey(key)) {
                pscsByPair.put(key, new List<npsp__Partial_Soft_Credit__c>());
            }
            pscsByPair.get(key).add(psc);
        }

        // ---------------------------------------------------------------
        // Pass 3: business validation against opportunity data (no DML)
        // ---------------------------------------------------------------
        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppsById.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException(
                    'Opportunity ' + req.opportunityId + ' was not found or is not visible to the running user.'
                );
            }
            if (req.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException(
                    'Contact ' + req.contactId + ' is the primary contact of opportunity ' +
                    req.opportunityId + ' and cannot receive a partial soft credit.'
                );
            }
            Decimal oppAmount = 0;
            if (opp.Amount != null) {
                oppAmount = opp.Amount;
            }
            if (req.amount > oppAmount) {
                throw new SoftCreditException(
                    'Soft credit amount ' + req.amount + ' exceeds the opportunity amount ' + oppAmount +
                    ' (opportunity ' + req.opportunityId + ').'
                );
            }
        }

        // ---------------------------------------------------------------
        // Pass 4: plan contact role changes (in memory)
        // ---------------------------------------------------------------
        List<OpportunityContactRole> ocrsToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToDelete = new List<OpportunityContactRole>();
        Map<String, OpportunityContactRole> keeperOcrByPair = new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest req : requests) {
            String key = pairKey(req.opportunityId, req.contactId);
            List<OpportunityContactRole> existing = ocrsByPair.get(key);

            if (existing == null || existing.isEmpty()) {
                OpportunityContactRole newOcr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
                ocrsToInsert.add(newOcr);
                keeperOcrByPair.put(key, newOcr);
                continue;
            }

            OpportunityContactRole keeper = chooseContactRole(existing, req.role);
            keeperOcrByPair.put(key, keeper);

            if (keeper.Role != req.role) {
                // Minimal record: only the Id and the field being changed.
                ocrsToUpdate.add(new OpportunityContactRole(
                    Id = keeper.Id,
                    Role = req.role
                ));
            }

            // Exactly one contact role per contact on the opportunity: remove any extras.
            for (OpportunityContactRole ocr : existing) {
                if (ocr.Id != keeper.Id) {
                    ocrsToDelete.add(new OpportunityContactRole(Id = ocr.Id));
                }
            }
        }

        // ---------------------------------------------------------------
        // DML 1: create new contact roles (needed before soft credits can reference them)
        // ---------------------------------------------------------------
        if (!ocrsToInsert.isEmpty()) {
            insert ocrsToInsert;
        }

        // ---------------------------------------------------------------
        // Pass 5: plan partial soft credits (contact role Ids are now known)
        // ---------------------------------------------------------------
        List<npsp__Partial_Soft_Credit__c> pscsToInsert = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> pscsToUpdate = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> pscsToDelete = new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            String key = pairKey(req.opportunityId, req.contactId);
            String contactRoleId = String.valueOf(keeperOcrByPair.get(key).Id);
            List<npsp__Partial_Soft_Credit__c> existing = pscsByPair.get(key);

            if (existing == null || existing.isEmpty()) {
                pscsToInsert.add(new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId,
                    npsp__Amount__c = req.amount,
                    npsp__Role_Name__c = req.role,
                    npsp__Contact_Role_ID__c = contactRoleId
                ));
                continue;
            }

            npsp__Partial_Soft_Credit__c keeperPsc = choosePartialSoftCredit(existing, contactRoleId);
            // Minimal record: only the Id and the fields this service sets.
            pscsToUpdate.add(new npsp__Partial_Soft_Credit__c(
                Id = keeperPsc.Id,
                npsp__Amount__c = req.amount,
                npsp__Role_Name__c = req.role,
                npsp__Contact_Role_ID__c = contactRoleId
            ));

            // One partial soft credit per contact per opportunity: remove any extras.
            for (npsp__Partial_Soft_Credit__c psc : existing) {
                if (psc.Id != keeperPsc.Id) {
                    pscsToDelete.add(new npsp__Partial_Soft_Credit__c(Id = psc.Id));
                }
            }
        }

        // ---------------------------------------------------------------
        // DML 2: update changed contact roles and existing soft credits (one mixed statement)
        // ---------------------------------------------------------------
        List<SObject> recordsToUpdate = new List<SObject>();
        recordsToUpdate.addAll(ocrsToUpdate);
        recordsToUpdate.addAll(pscsToUpdate);
