    private static npsp__Partial_Soft_Credit__c choosePartialSoftCredit(
            List<npsp__Partial_Soft_Credit__c> candidates,
            String contactRoleId) {
        for (npsp__Partial_Soft_Credit__c psc : candidates) {
            if (contactRoleId.equals(psc.npsp__Contact_Role_ID__c)) {
                return psc;
            }
        }
        return candidates[0];
