/**
 * Trigger Actions Framework action that prevents two Contacts on the same Account
 * from sharing an email address (compared case-insensitively).
 *
 * - Contacts without an AccountId or an Email are not checked.
 * - On update, only contacts whose Email or AccountId changed are checked, so legacy
 *   duplicates do not block unrelated edits. A contact never conflicts with itself.
 * - Within a single save, the first offending contact in the list is accepted and each
 *   later conflicting contact is rejected.
 * - Bulk safe: at most one SOQL query per execution.
 */
public inherited sharing class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    @TestVisible
    private static final String DUPLICATE_EMAIL_MESSAGE =
        'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> contacts = toContacts(triggerNew);
        enforceUniqueEmail(contacts, new Map<Id, Contact>(), false);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> contacts = toContacts(triggerNew);

        Map<Id, Contact> oldById = new Map<Id, Contact>();
        if (triggerOld != null) {
            for (SObject old : triggerOld) {
                Contact oldContact = (Contact) old;
                oldById.put(oldContact.Id, oldContact);
            }
        }
        enforceUniqueEmail(contacts, oldById, true);
    }

    private static List<Contact> toContacts(List<SObject> records) {
        List<Contact> contacts = new List<Contact>();
        if (records == null) {
            return contacts;
        }
        for (SObject record : records) {
            contacts.add((Contact) record);
        }
        return contacts;
    }

    /**
     * @param contacts   the records being saved, in trigger order
     * @param oldById    prior state keyed by Id (updates only)
     * @param isUpdate   true for before update, false for before insert
     */
    private static void enforceUniqueEmail(
            List<Contact> contacts,
            Map<Id, Contact> oldById,
            Boolean isUpdate) {

        if (contacts.isEmpty()) {
            return;
        }

        // Ids of every record in this save. Their stored values are stale, so the query
        // ignores them and their final values are evaluated in memory instead.
        Set<Id> batchIds = new Set<Id>();

        // Per-record data, aligned by index with contacts.
        List<String> keys = new List<String>();
        List<Boolean> mustCheck = new List<Boolean>();

        // Query filter values, restricted to records that must be checked.
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        for (Contact c : contacts) {
            String key = keyOf(c);
            Boolean check = false;

            if (isUpdate && c.Id != null) {
                batchIds.add(c.Id);
            }

            if (key != null) {
                if (!isUpdate) {
                    check = true;
                } else {
                    Contact oldContact = c.Id == null ? null : oldById.get(c.Id);
                    check = oldContact == null
                        || c.Email != oldContact.Email
                        || c.AccountId != oldContact.AccountId;
                }
            }

            keys.add(key);
            mustCheck.add(check);

            if (check) {
                accountIds.add(c.AccountId);
                emails.add(c.Email.toLowerCase());
            }
        }

        // Keys already held by stored contacts that are not part of this save.
        Set<String> claimed = new Set<String>();

        // The single SOQL query for this execution.
        if (!emails.isEmpty()) {
            List<Contact> stored = [
                SELECT Id, AccountId, Email
                FROM Contact
                WHERE AccountId IN :accountIds
                AND Email IN :emails
            ];
            for (Contact existing : stored) {
                if (batchIds.contains(existing.Id)) {
                    continue;
                }
                String existingKey = keyOf(existing);
                if (existingKey != null) {
                    claimed.add(existingKey);
                }
            }
        }

        // Contacts in this save that are not checked (unchanged on update) keep their
        // current email and account, so they hold their key for the rest of the save.
        for (Integer i = 0; i < keys.size(); i++) {
            if (keys[i] != null && !mustCheck[i]) {
                claimed.add(keys[i]);
            }
        }

        // Checked contacts in list order: the first one claims the key, later ones fail.
        for (Integer i = 0; i < contacts.size(); i++) {
            if (!mustCheck[i]) {
                continue;
            }
            if (claimed.contains(keys[i])) {
                contacts[i].addError(DUPLICATE_EMAIL_MESSAGE);
            } else {
                claimed.add(keys[i]);
            }
        }
    }

    /**
     * Returns the account/email key used for the duplicate check, or null when the
     * contact is not subject to the rule (no Account or no Email).
     */
    private static String keyOf(Contact c) {
        if (c.AccountId == null || String.isBlank(c.Email)) {
            return null;
        }
        return String.valueOf(c.AccountId) + '|' + c.Email.toLowerCase();
    }
}
