```apex
/**
 * Keeps Account.FB_Open_Case_Count__c equal to the number of the account's Cases where IsClosed = false.
 *
 * Registered through Trigger_Action__mdt records on Case for after insert, after update,
 * after delete and after undelete (TA_Case_RollupOpenCount_AI, _AU, _AD and _AUD).
 *
 * Limits per trigger execution, whatever the batch size:
 *   - 2 SOQL queries: one aggregate over Case, one over Account.
 *   - 1 DML statement: one update on the Accounts whose stored counter is wrong.
 *
 * Runs without sharing on purpose: the counter must reflect every Case on the account, not only
 * the Cases the running user can see. The only field written is the system-maintained counter.
 */
public without sharing class TA_Case_RollupOpenCount implements
        TriggerAction.AfterInsert,
        TriggerAction.AfterUpdate,
        TriggerAction.AfterDelete,
        TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        collectAccountIds(triggerNew, accountIds);
        recalculate(accountIds);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, SObject> oldById = new Map<Id, SObject>(triggerOld);
        Set<Id> accountIds = new Set<Id>();

        for (SObject rec : triggerNew) {
            Case newCase = (Case) rec;
            Case oldCase = (Case) oldById.get(newCase.Id);

            // Only an account change or an open/closed change can alter any count.
            if (newCase.AccountId != oldCase.AccountId || newCase.IsClosed != oldCase.IsClosed) {
                addAccountId(accountIds, newCase.AccountId);
                addAccountId(accountIds, oldCase.AccountId);
            }
        }

        recalculate(accountIds);
    }

    public void afterDelete(List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        collectAccountIds(triggerOld, accountIds);
        recalculate(accountIds);
    }

    public void afterUndelete(List<SObject> triggerNew) {
        Set<Id> accountIds = new Set<Id>();
        collectAccountIds(triggerNew, accountIds);
        recalculate(accountIds);
    }

    private static void collectAccountIds(List<SObject> records, Set<Id> accountIds) {
        for (SObject rec : records) {
            addAccountId(accountIds, ((Case) rec).AccountId);
        }
    }

    private static void addAccountId(Set<Id> accountIds, Id accountId) {
        if (accountId != null) {
            accountIds.add(accountId);
        }
    }

    private static void recalculate(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        // SOQL 1: open Case count per affected account. Accounts with no open Case are absent.
        // Plain fields cannot be aliased in SOQL, so the grouped AccountId is read by its name.
        Map<Id, Integer> openCountByAccountId = new Map<Id, Integer>();
        for (AggregateResult ar : [
            SELECT AccountId, COUNT(Id) openCases
            FROM Case
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            openCountByAccountId.put((Id) ar.get('AccountId'), (Integer) ar.get('openCases'));
        }

        // SOQL 2: current stored counter for the affected accounts.
        List<Account> accounts = [
            SELECT Id, FB_Open_Case_Count__c
            FROM Account
            WHERE Id IN :accountIds
        ];

        List<Account> toUpdate = new List<Account>();
        for (Account acc : accounts) {
            // An account without open Cases must show 0, not blank.
            Integer expected = openCountByAccountId.containsKey(acc.Id)
                ? openCountByAccountId.get(acc.Id)
                : 0;
            Integer stored = acc.FB_Open_Case_Count__c == null
                ? null
                : acc.FB_Open_Case_Count__c.intValue();

            if (stored != expected) {
                toUpdate.add(new Account(Id = acc.Id, FB_Open_Case_Count__c = expected));
            }
        }

        // DML 1: write only the counters that actually changed.
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
