```apex
public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {

    // Ids of Opportunities already evaluated in this transaction. TA_Opportunity_RoundAmount
    // updates the same records, which re-runs this action for them. Only the first evaluation
    // may log, so the rounding pass cannot create a second task for the same user change.
    @TestVisible
    private static Set<Id> evaluatedIds = new Set<Id>();

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, SObject> oldById = new Map<Id, SObject>(triggerOld);

        List<Task> auditTasks = new List<Task>();
        for (SObject record : triggerNew) {
            Opportunity opp = (Opportunity) record;

            // Set.add returns false when this Id was already evaluated in this transaction.
            if (!evaluatedIds.add(opp.Id)) {
                continue;
            }

            Opportunity oldOpp = (Opportunity) oldById.get(opp.Id);
            if (oldOpp == null) {
                continue;
            }

            if (opp.Amount != oldOpp.Amount) {
                auditTasks.add(new Task(
                    Subject = 'Amount changed',
                    WhatId = opp.Id,
                    Status = 'Completed'
                ));
            }
        }

        // One DML statement per trigger execution, regardless of batch size.
        if (!auditTasks.isEmpty()) {
            insert auditTasks;
        }
    }
}
