/**
 * Before insert: when a Contact has an Account and all four mailing address fields are blank,
 * copies the Account's billing address into the Contact's mailing address.
 * Uses the shared Account map from TA_Contact_Queries; performs no queries itself.
 */
public inherited sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {

    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (Contact con : (List<Contact>) triggerNew) {
            if (con.AccountId == null || hasMailingAddress(con)) {
                continue;
            }

            Account parent = accountsById.get(con.AccountId);
            if (parent == null) {
                continue;
            }

            con.MailingStreet = parent.BillingStreet;
            con.MailingCity = parent.BillingCity;
            con.MailingPostalCode = parent.BillingPostalCode;
            con.MailingCountry = parent.BillingCountry;
        }
    }

    private static Boolean hasMailingAddress(Contact con) {
        return String.isNotBlank(con.MailingStreet)
            || String.isNotBlank(con.MailingCity)
            || String.isNotBlank(con.MailingPostalCode)
            || String.isNotBlank(con.MailingCountry);
    }
}
